// --- ArenaFrame usage (Category C) ---
// UNPROTECT itself performs no allocation and has no interaction with the
// arena allocator.  The SEXP objects it conceptually releases (allocVector /
// allocMatrix results) are heap-allocated via malloc() and are not freed by
// UNPROTECT — they survive until the Python caller invokes free_sexp() /
// free_sexp_deep() after extracting element data into numpy arrays.
//
// The ArenaFrame guard governs only R_alloc / ALLOC scratch arrays, which
// are managed by a completely separate subsystem from the PROTECT/UNPROTECT
// family.
//
// All four functions that contain UNPROTECT calls (pred_rpart, rpart,
// rpartexp2, xpred) also use ALLOC / R_alloc scratch allocations.  Their
// .Call-entry wrapper functions must declare `ArenaFrame _frame;` as the
// first statement to free those scratch arrays on exit or exception:
//
//   SEXP pred_rpart_entry(...) {
//       ArenaFrame _frame;   // <-- frees R_alloc/ALLOC scratch on exit
//       try {
//           return pred_rpart(...);
//       } catch (const RError &e) {
//           set_python_error(e.what());
//           return R_NilValue;
//       }
//   }
//
// Inside pred_rpart(), the PROTECT/UNPROTECT sequence expands as:
//   SEXP where = PROTECT(allocVector(INTSXP, n));
//   =>  SEXP where = Rf_protect(allocVector(INTSXP, n));
//   =>  SEXP where = allocVector(INTSXP, n);  // Rf_protect is identity
//   ...
//   UNPROTECT(1);
//   =>  Rf_unprotect(1);
//   =>  (nothing — empty body, call eliminated by compiler)
//   return where;  // where is a valid heap-allocated INTSXP
//
// Inside rpart(), the variable-expression argument is handled identically:
//   UNPROTECT(1 + nout);
//   =>  Rf_unprotect(1 + nout);
//   =>  (nothing — nout is in scope as int, no side effects)
//   return rlist;  // rlist is a valid heap-allocated VECSXP
//
// Python side: call free_sexp_deep(rlist) after extracting results from
// rlist's child SEXPs, to release the entire VECSXP tree.

#endif // FAKE_UNPROTECT_H
